public Map addTranslations()
{
    Map ret = super();
    ret.insert('CreateTransferJournalLine',"@SYS319116");
    ret.insert('CreateTransferJournal', "@SYS18287");
    ret.insert('Post', "@SYS6098");
    return ret;
}

public TFMDocumentHandlerDescription description()
{
    return "@SYS144119";
}

public TFMPages pages()
{    
    TFMPages    pages = MobInventJournalTableCommon::modifyPages(super(),InventJournalType::Transfer, "@SYS318133",  methodstr(MobimageHandlerCombinedImages, transferJournalIcon), true);
    TFMPageUnplannedItemRegistration uirPage = pages.getPage('DeleteJournalLine');

    TFMPageUnplannedItemRegistrationConfiguration config =  uirPage.getConfiguration();

    config.parmClose(true);

    TFMPageUnplannedItemRegistration pjPage = pages.getPage('PostJournal');

    pjPage.parmIcon(resourceStr(MobPost));

    return pages;
}

/// <summary>
/// Creates a delete journal Line Configuration.
/// </summary>
protected Map createDeleteJournalLineConfiguration()
{
    Map ReturnMap = new Map(Types::Integer, Types::Class);

    // Add a step to ask the user if the line should be deleted
    ReturnMap.insert(10, TFMRegistrationCollectorRadioButton::RadioButtonStepMap(10,MobConstants::YesNo(),"@SYS304126","@SYS21354",'',"@SYS5461","@SYS5461"+';'+"@SYS2048"));

    return ReturnMap;
}

/// <summary>
/// Method to delete Inventory journal trans lines.
/// </summary>
[TFMPostMethod(tableStr(inventJournalTable)),TFMPostMethod(tableStr(inventJournalTrans))]
public void postDeleteInventJournalTransLine()
{
    Common      common = docRequest.getReferredRecord();
    WHSLicensePlate LP;
    InventJournalTrans      line;
    InventJournalTrans_Tag  tagLine;
    InventDim           iDim;
    InventJournalId     journalId = docRequest.parmJournalId();
    if (!journalId && docRequest.parmContextValues())
    {
        journalId = docRequest.parmContextValues().getFieldValue(MobConstants::JournalId());
    }
    if (docRequest.getFieldValue(MobConstants::YesNo()) == "@SYS2048")
    {
        return;
    }

    ttsbegin;
    if (common.tableId == tableNum(InventJournalTrans) || common.tableId == tableNum(InventJournalTrans_tag))
    {
        common.selectForUpdate(true);
        common.delete();
    }
    else
    {
        LP = common;
        delete_from line
            where line.JournalId == journalId
            exists join iDim where iDim.inventDimId == line.InventDimId && iDim.LicensePlateId == LP.LicensePlateId;
        delete_from tagLine
            where tagLine.JournalId == journalId
            exists join iDim where iDim.inventDimId == tagLine.InventDimId && iDim.LicensePlateId == LP.LicensePlateId;

    }    



    ttscommit;        
}

[TFMReferenceDataMethod]
public TFMReferenceDataConfiguration CreateTransferJournalHeader()
{
    TFMReferenceDataConfiguration conf = new TFMReferenceDataConfiguration();
    TFMRegistrationCollectorText	journalDesc = new TFMRegistrationCollectorText(1,extendedTypeStr(Description),"@SYS6303","@SYS6303","@SYS6303");


    journalDesc.parmOptional(false);
    conf.addCollector(journalDesc);

    return conf;
}

[TFMReferenceDataMethod]
public TFMReferenceDataConfiguration DeleteJournalLineHeader()
{
    TFMReferenceDataConfiguration conf = new TFMReferenceDataConfiguration();

    conf.addCollector(TFMGetReferenceData::defaultReferenceIdentity(10));

    return conf;
}

/// <summary>
/// Method to create the filter/header for the create Profit/Loss page.
/// </summary>
/// <returns>The Filter as an XML formatted string.</returns>
[TFMReferenceDataMethod]
public TFMReferenceDataConfiguration CreateTransferJournalLineHeader()
{
    TFMReferenceDataConfiguration refConf = this.TransferJournalCfgHeader();
    TFMRegistrationCollectorList    fromWarehouse = TFMGetReferenceData::createDefaultWarehouseReferenceData(10, strLwr(extendedTypeStr(InventLocationId)), "@SYS25253", methodStr(TFMGetReferenceData,WarehouseList));
    // Warehouse to move from
    fromWarehouse.parmLinkedElement(20);
    fromWarehouse.parmLinkColumn(extendedTypeStr(InventLocationId));
    refConf.addCollector(fromWarehouse);
    // Warehouse to move to
    refConf.addCollector(TFMGetReferenceData::createDefaultWarehouseReferenceData(20,'To'+ strLwr(extendedTypeStr(InventLocationId)), "@SYS8519", methodStr(TFMGetReferenceData,WarehouseList)));
    // Item number text box
    refConf.addCollector(TFMGetReferenceData::defaultItemIdOrLPCollector(30));

    return refConf;
}

