public boolean preProcess()
{

    // Get the dimension setup for the item
    docRequest = request;
    return true;
}

/// <summary>
/// Method to create Profit/Loss Journal line configurations.
/// </summary>

public Map createCreatePLJournalLineConfiguration()
{
    Map returnMap;
    MobDocUnplannedMove docUnplannedMove;
    SysDictType         dictType;

    MobDocTransferJournal::handleDefaultItemIdOrLPCollector(docRequest);

    if (docRequest.parmItemId())
    {

        //Single Item
        docUnplannedMove = new MobDocUnplannedMove();
        docUnplannedMove.parmRequest(docRequest);
        docUnplannedMove.preProcess();
        return docUnplannedMove.unplannedMoveRegistrationCollectors();
    } 
    else if (docRequest.parmLicensePlateId())
    {
        //License plate, ask for to location        
        returnMap = new Map(Types::String, Types::Class);
        dictType = new SysDictType(extendedTypeNum(WMSLocationId));
        returnMap.insert(MobConstants::ToLocation(),TFMRegistrationCollectorText::TextStepMap(false,30,'To' + extendedTypeStr(WMSLocationId),"@MobileWMS:MEL44","@SYS50351","@MobileWMS:MEL45",dictType.stringLen()));
    } 

    return returnMap;
}

/// <summary>
/// Method to create Profit/Loss journals.
/// </summary>
[TFMPostMethod(tableStr(inventJournalTable))]
public void postCreateTransferJournal()
{
    InventJournalTableData		jourTableData;
    InventJournalName			inventJournalName;

    str							description			= docRequest.getFieldValue(extendedTypeStr(description));
    InventLocationId            inventLocationId    = docRequest.parmContextValues().getFieldValue(extendedTypeStr(InventLocationId));


    // Get the name of the profit/loss journal to create
    inventJournalName = InventJournalName::find(MobParameters::find().InventJournalNameTransfer,true);

    ttsBegin;

    jourTableData = JournalTableData::newTable(inventJournalTable);

    inventJournalTable.JournalId            = jourTableData.nextJournalId();
    inventJournalTable.JournalType          = inventJournalType::Transfer;
    inventJournalTable.MobReleasedToMobile  = true;
    inventJournalTable.NumOfLines           = 0;

    inventJournalTable.InventLocationId		= inventLocationId;
    inventJournalTable.InventSiteId			= InventLocation::find(inventLocationId).InventSiteId;

    jourTableData.initFromJournalName(inventJournalName);
    inventJournalTable.Description          = description;

    inventJournalTable.insert();
    ttsCommit;

    resultStr = "@MobileWMS:TransferJournalcreatedsuccesfull";
}

/// <summary>
/// Method to create Profit/Loss journal lines.
/// </summary>
[TFMPostMethod(tableStr(inventJournalTable)),TFMPostMethod(tableStr(inventJournalTrans))]
public void postCreateTransferJournalLine()
{
    InventDim           inventDimIssue;
    InventDim           inventDimReceipt;        
    Qty                 qty;

    MobDocTransferJournal::handleDefaultItemIdOrLPCollector(docRequest);
    ItemId              itemId = docRequest.parmItemId();

    inventJournalTable = InventJournalTable::find(docRequest.parmJournalId(),true);

    if (!itemId && docRequest.parmLicensePlateId())
    {
        //License Plæjt
        MobPostHelper::AddMoveLicensePlateToJournal(inventJournalTable, docRequest.parmLicensePlateId(),docRequest.parmToInventLocationId(), docRequest.parmToWMSLocationId());
        MobPostHelper::validateInventJournalTransfer(inventJournalTable);
        resultStr =  "@MobileWMS:MEL47";
        return;
    }

    inventDimIssue.data(docRequest.parmInventDim());
    inventDimReceipt.data(docRequest.parmInventDim());

    inventDimIssue = docRequest.createFromInventDim(inventDimIssue);
    inventDimReceipt = docRequest.createToInventDim(inventDimReceipt);
    qty = docRequest.parmQuantity();


    inventJournalTrans = MobPostHelper::inventJournalTransferLineCreate(inventJournalTable, qty,itemId,inventDimIssue, inventDimReceipt);

    MobPostHelper::validateInventJournalTransfer(inventJournalTable);
    resultStr =  "@MobileWMS:MEL47";
}

public void postUpdateTransferJournalLine()
{

    inventJournalTable = InventJournalTable::find(docRequest.parmJournalId(),true);


    // Update Line(s)
    this.updateJournalLines(docRequest.getReferredRecord(), docRequest.parmToWMSLocationId(), docRequest.parmJournalId());
    MobPostHelper::validateInventJournalTransfer(inventJournalTable);
    resultStr =  "@MobileWMS:MEL47";


}

protected void updateJournalLines(Common _line, WMSLocationId _wmsLocation, InventJournalId _journalId)
{
    InventJournalTrans  line;
    WHSLicensePlate     LP;
    InventDim           iDim, iDimTo;
    ttsbegin;
    if (_line.tableId == tableNum(InventJournalTrans))
    {
        line = _line;
        line.selectForUpdate(true);
        iDimTo = line.ToInventDim();
        iDimTo.wmsLocationId = _wmsLocation;
        line.ToinventDimID = InventDim::findOrCreate(iDimTo).inventDimId;
        line.update();
    }
    else
    {
        LP = _line;
        while select forupdate line
            where line.JournalId == _journalId
            join iDim where iDim.inventDimId == line.InventDimId && iDim.LicensePlateId == LP.LicensePlateId
        {
            iDimTo = line.ToInventDim();
            iDimTo.wmsLocationId = _wmsLocation;
            line.ToinventDimID = InventDim::findOrCreate(iDimTo).inventDimId;
            line.update();
        }
    }

    ttscommit;
}

[TFMDocumentType(classStr(TFMPostAdhocRegistration), 'PostJournal')]
public str postJournal()
{
    ttsbegin;
    inventJournalTable = inventJournalTable::find(docRequest.parmJournalId(),true);

    MobPostHelper::postInventJournalTransfer(inventJournalTable);
    ttscommit;
    return '';
}

/// <summary>
/// This was previously done in the TFMRequestInventDimElement. The new process handling in 4.0 copies the values in a block instead.
/// This is to support the (Revert to Classic versions of the processes)
/// </summary>
public static void handleDefaultItemIdOrLPCollector(TFMRequestInventDimElement _docRequest)
{
    InventDim   localInventDim;

    str combinedHeaderName = extendedTypeStr(ItemId) + extendedTypeStr(WHSLicensePlateId);
    str itemIdWHSLicensePlateId  = _docRequest.getFieldValue(combinedHeaderName);

    if(itemIdWHSLicensePlateId)
    {
        if (WHSLicensePlate::exist(itemIdWHSLicensePlateId))
        {
            _docRequest.parmLicensePlateId(itemIdWHSLicensePlateId);
        }
        else
        {
            _docRequest.parmItemId(itemIdWHSLicensePlateId);
        }
    }
}
